INSERT INTO `peralatan` (`id`, `kode_barang`, `nama_barang`, `kategori_id`, `jumlah`, `jumlah_tersedia`, `kondisi`, `lokasi`, `deskripsi`, `foto`, `status`, `created_at`, `updated_at`) VALUES ('5', 'IOT-ESP-002', 'ESP32 NodeMCU Wi-Fi & Bluetooth Dev Board', '5', '15', '15', 'Baik', 'Rak IoT Lab RPL - Box A2', 'Board mikrokontroler dual-core Tensilica Xtensa 32-bit LX6 dengan konektivitas Wi-Fi 802.11 b/g/n dan Bluetooth 4.2 BLE untuk proyek IoT web service, REST API, dan MQTT subscriber/publisher.', 'assets/uploads/peralatan/alat_iot_esp_002.jpg', 'aktif', '2026-09-24 14:29:13', '2026-10-16 12:45:52');
INSERT INTO `peralatan` (`id`, `kode_barang`, `nama_barang`, `kategori_id`, `jumlah`, `jumlah_tersedia`, `kondisi`, `lokasi`, `deskripsi`, `foto`, `status`, `created_at`, `updated_at`) VALUES ('6', 'IOT-RPI-003', 'Raspberry Pi 4 Model B (4GB RAM) Single Board Computer', '5', '8', '7', 'Baik', 'Lemari IoT Khusus - Rak A3', 'Komputer mini Quad Core Cortex-A72 1.5GHz, 4GB LPDDR4, dual display micro-HDMI 4K, Gigabit Ethernet, USB 3.0 untuk deployment server web lokal, computer vision, dan AI edge computing.', 'assets/uploads/peralatan/alat_iot_rpi_003.jpg', 'aktif', '2026-09-24 14:29:13', '2026-09-24 14:29:13');
INSERT INTO `peralatan` (`id`, `kode_barang`, `nama_barang`, `kategori_id`, `jumlah`, `jumlah_tersedia`, `kondisi`, `lokasi`, `deskripsi`, `foto`, `status`, `created_at`, `updated_at`) VALUES ('7', 'IOT-SNS-004', 'Sensor Kit 37-in-1 Lengkap Praktikum IoT', '5', '10', '10', 'Baik', 'Rak IoT Lab RPL - Box B1', 'Set sensor terpadu 37 jenis komponen mencakup sensor suhu kelembaban DHT11, ultrasonik HC-SR04, PIR motion, LDR, soil moisture, relay 1-channel, gas MQ-2, sound sensor, dan joystick modul.', 'assets/uploads/peralatan/alat_iot_sns_004.jpg', 'aktif', '2026-09-24 14:29:13', '2026-09-24 14:29:13');
INSERT INTO `peralatan` (`id`, `kode_barang`, `nama_barang`, `kategori_id`, `jumlah`, `jumlah_tersedia`, `kondisi`, `lokasi`, `deskripsi`, `foto`, `status`, `created_at`, `updated_at`) VALUES ('8', 'IOT-CAM-005', 'Modul Kamera ESP32-CAM OV2640 + Downloader FTDI', '5', '8', '8', 'Baik', 'Rak IoT Lab RPL - Box B2', 'Modul ESP32 dengan sensor kamera OV2640 2MP dan slot MicroSD untuk praktikum streaming video CCTV IoT, face recognition, OCR, dan QR code decoding nirkabel.', 'assets/uploads/peralatan/alat_iot_cam_005.jpg', 'aktif', '2026-09-24 14:29:13', '2026-10-16 12:45:52');
