INSERT INTO `peralatan` (`id`, `kode_barang`, `nama_barang`, `kategori_id`, `jumlah`, `jumlah_tersedia`, `kondisi`, `lokasi`, `deskripsi`, `foto`, `status`, `created_at`, `updated_at`) VALUES ('10', 'NET-TST-002', 'Digital Network LAN Cable Tester RJ45 & RJ11 LCD', '6', '10', '9', 'Baik', 'Rak Jaringan - Tool Bag N2', 'Tester kabel LAN dengan master dan remote unit indikator LED multi-wire untuk mendeteksi kabel straight-through, crossover, open pin, short circuit, dan miswire secara cepat.', 'assets/uploads/peralatan/alat_net_tst_002.jpg', 'aktif', '2026-09-24 14:29:13', '2026-09-24 14:29:13');
