INSERT INTO `peralatan` (`id`, `kode_barang`, `nama_barang`, `kategori_id`, `jumlah`, `jumlah_tersedia`, `kondisi`, `lokasi`, `deskripsi`, `foto`, `status`, `created_at`, `updated_at`) VALUES ('12', 'NET-WFI-004', 'Access Point Dual-Band Gigabit TP-Link Archer C6 MU-MIMO', '6', '6', '6', 'Baik', 'Lemari Rack Server - Rak J2', 'Wireless router/AP AC1200 Dual-Band 2.4GHz (300Mbps) dan 5GHz (867Mbps) dengan 4 antena eksternal 5dBi dan teknologi MU-MIMO untuk pengujian hotspot siswa, captive portal, dan isolasi klien.', 'assets/uploads/peralatan/alat_net_wfi_004.jpg', 'aktif', '2026-09-24 14:29:14', '2026-10-16 12:45:52');
